/**
 * CSS-переменные в инлайновом стиле (TRIP-388).
 *
 * ★ ЗАЧЕМ. React проставляет `style={{ '--ac': … }}` в рантайме без вопросов, но
 * `CSSProperties` из @types/react 18 произвольных `--*` НЕ допускает, поэтому у
 * любого файла под `// @ts-check` такая строка даёт TS2353. В репозитории таких
 * мест 14 в 8 файлах — то есть на пересадке экранов это всплывает снова и снова.
 *
 * ★★ ПОЧЕМУ ОБЪЯВЛЕНИЕ, А НЕ КАСТ НА МЕСТЕ. Локальный каст
 * `style={/** @type {any} *​/ ({…})}` тоже убирает ошибку, но он МЕНЯЕТ ТЕКСТ и
 * тем самым уводит инлайн из-под шаблона `style={{`, которым его считает
 * `audit-design.mjs`. Замерено: число инлайнов падало 686 → 685 БЕЗ единого
 * снятого инлайна. Метрика захраповлена ВНИЗ, поэтому такое «улучшение»
 * проходит молча и навсегда занижает планку. Объявление оставляет разметку
 * нетронутой — счёт остаётся честным.
 *
 * Границы: объявление НЕ проверяет, что переменная где-то объявлена в CSS, и не
 * ограничивает набор имён. Оно снимает ровно ложную ошибку типа и ничего больше;
 * рантайм не затрагивается никак.
 */
import 'react';

declare module 'react' {
  interface CSSProperties {
    [key: `--${string}`]: string | number | undefined;
  }
}
